#!/usr/bin/env node

// Generated by Gemini
// Run from the monorepo root

const fs = require('fs');
const path = require('path');

// Find repo root relative to script location (bin/check-release-discrepancies.cjs)
const REPO_ROOT = path.resolve(__dirname, '..');

// Colors
const RED = '\x1b[31m';
const GREEN = '\x1b[32m';
const YELLOW = '\x1b[33m';
const CYAN = '\x1b[36m';
const BOLD = '\x1b[1m';
const RESET = '\x1b[0m';

// Parse args
const args = process.argv.slice(2);
const showAll = args.includes('--all') || args.includes('-a');
const onlyCritical = args.includes('--only-newer') || args.includes('-n');
const help = args.includes('--help') || args.includes('-h');
let concurrency = 10;
const limitIdx = args.findIndex(a => a === '--concurrency' || a === '-c');
if (limitIdx !== -1 && args[limitIdx + 1]) {
  concurrency = parseInt(args[limitIdx + 1], 10) || 10;
}

if (help) {
  console.log(`${BOLD}google-cloud-node Package Release Discrepancy Checker${RESET}`);
  console.log('\nChecks all local Node.js packages against the NPM registry to find released version mismatches.\n');
  console.log(`${BOLD}Usage:${RESET}`);
  console.log('  ./bin/check-release-discrepancies.sh [options]\n');
  console.log(`${BOLD}Options:${RESET}`);
  console.log('  -a, --all            Show all checked packages, including those that match.');
  console.log('  -n, --only-newer     Only show critical discrepancies (where NPM version is newer than local).');
  console.log('  -c, --concurrency N  Number of concurrent registry requests (default: 10).');
  console.log('  -h, --help           Show this help message.');
  process.exit(0);
}

// Find all package.json files recursively
function findPackageJsons(dir, results = []) {
  const list = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of list) {
    const name = entry.name;
    const res = path.resolve(dir, name);
    if (entry.isDirectory()) {
      if (
        name === 'node_modules' ||
        name.startsWith('.') ||
        name === 'test' ||
        name === 'tests' ||
        name === 'test-fixtures' ||
        name === 'fixtures' ||
        name === 'baselines' ||
        name === 'samples' ||
        name === 'system-test' ||
        name === 'system-tests' ||
        name === 'templates' ||
        name === 'template' ||
        name.includes('template')
      ) {
        continue;
      }
      findPackageJsons(res, results);
    } else if (name === 'package.json') {
      results.push(res);
    }
  }
  return results;
}

console.log(`${CYAN}Scanning repository for packages...${RESET}`);
const packageJsonPaths = findPackageJsons(REPO_ROOT);
const packages = [];

for (const p of packageJsonPaths) {
  try {
    const content = fs.readFileSync(p, 'utf8');
    const json = JSON.parse(content);
    if (json.private) {
      continue; // Skip private packages
    }
    if (json.name && json.version) {
      // Skip template package.json files
      if (json.name.includes('{{') || json.name.includes('${') || json.name.includes('<%')) {
        continue;
      }
      packages.push({
        name: json.name,
        localVersion: json.version,
        path: path.relative(REPO_ROOT, path.dirname(p)) || '.'
      });
    }
  } catch (err) {
    // Skip malformed package.json files
  }
}

console.log(`Found ${BOLD}${packages.length}${RESET} public packages.`);

if (packages.length === 0) {
  console.log('No packages found to check.');
  process.exit(0);
}

// Version comparison
function compareVersions(v1, v2) {
  const clean = (v) => v.replace(/^[^0-9]+/, '');
  const parts1 = clean(v1).split(/[-+]/)[0].split('.').map(Number);
  const parts2 = clean(v2).split(/[-+]/)[0].split('.').map(Number);
  for (let i = 0; i < Math.max(parts1.length, parts2.length); i++) {
    const p1 = parts1[i] || 0;
    const p2 = parts2[i] || 0;
    if (p1 > p2) return 1;
    if (p1 < p2) return -1;
  }
  
  const idx1 = clean(v1).indexOf('-');
  const idx2 = clean(v2).indexOf('-');
  const pre1 = idx1 !== -1 ? clean(v1).substring(idx1 + 1) : null;
  const pre2 = idx2 !== -1 ? clean(v2).substring(idx2 + 1) : null;
  
  if (pre1 && !pre2) return -1;
  if (!pre1 && pre2) return 1;
  if (pre1 && pre2) {
    return pre1.localeCompare(pre2, undefined, { numeric: true, sensitivity: 'base' });
  }
  return 0;
}

// Concurrency queue
async function limitConcurrency(tasks, limit) {
  const results = [];
  const executing = new Set();
  for (const task of tasks) {
    const p = Promise.resolve().then(() => task());
    results.push(p);
    executing.add(p);
    const clean = () => executing.delete(p);
    p.then(clean, clean);
    if (executing.size >= limit) {
      await Promise.race(executing);
    }
    // Stagger task initiation slightly to prevent burst rate-limiting
    await new Promise(resolve => setTimeout(resolve, 150));
  }
  return Promise.all(results);
}

let completed = 0;
function updateProgress() {
  const total = packages.length;
  const percentage = Math.round((completed / total) * 100);
  const width = 30;
  const filledWidth = Math.round((percentage / 100) * width);
  const emptyWidth = width - filledWidth;
  const bar = '='.repeat(filledWidth) + (filledWidth < width ? '>' : '') + ' '.repeat(Math.max(0, emptyWidth - 1));
  process.stdout.write(`\r\x1b[36m[Checking NPM Registry]\x1b[0m Progress: ${percentage}% [${bar}] ${completed}/${total}`);
}

// Fetch wrapper with retry and exponential backoff on 429 rate limit
async function fetchWithRetry(url, options = {}, retries = 6, delay = 3000) {
  try {
    const res = await fetch(url, options);
    if (res.status === 429 && retries > 0) {
      const retryAfterHeader = res.headers.get('retry-after');
      const waitTime = retryAfterHeader ? (parseInt(retryAfterHeader, 10) * 1000) : delay;
      await new Promise(resolve => setTimeout(resolve, waitTime));
      return fetchWithRetry(url, options, retries - 1, delay * 2);
    }
    return res;
  } catch (err) {
    if (retries > 0) {
      await new Promise(resolve => setTimeout(resolve, delay));
      return fetchWithRetry(url, options, retries - 1, delay * 2);
    }
    throw err;
  }
}

const checkTasks = packages.map(pkg => async () => {
  try {
    const res = await fetchWithRetry(`https://registry.npmjs.org/${encodeURIComponent(pkg.name)}/latest`, {
      headers: { 'Accept': 'application/json' }
    });
    
    completed++;
    updateProgress();
    
    if (res.status === 404) {
      return { ...pkg, npmVersion: null, status: 'unreleased' };
    } else if (!res.ok) {
      return { ...pkg, npmVersion: null, status: 'error', error: `HTTP ${res.status}` };
    }
    
    const data = await res.json();
    const npmVersion = data.version;
    
    if (!npmVersion) {
      return { ...pkg, npmVersion: null, status: 'error', error: 'No version in registry' };
    }
    
    const cmp = compareVersions(pkg.localVersion, npmVersion);
    if (cmp === 0) {
      return { ...pkg, npmVersion, status: 'match' };
    } else if (cmp > 0) {
      return { ...pkg, npmVersion, status: 'local_ahead' };
    } else {
      return { ...pkg, npmVersion, status: 'npm_ahead' };
    }
  } catch (err) {
    completed++;
    updateProgress();
    return { ...pkg, npmVersion: null, status: 'error', error: err.message };
  }
});

updateProgress();

limitConcurrency(checkTasks, concurrency).then(results => {
  process.stdout.write('\r\x1b[K'); // Clear progress line
  
  const critical = results.filter(r => r.status === 'npm_ahead');
  const ahead = results.filter(r => r.status === 'local_ahead');
  const unreleased = results.filter(r => r.status === 'unreleased');
  const matches = results.filter(r => r.status === 'match');
  const errors = results.filter(r => r.status === 'error');

  // Print tables
  function printTable(title, titleColor, items) {
    if (items.length === 0) return;
    console.log('\n' + titleColor + '='.repeat(80) + RESET);
    console.log(titleColor + title + ` (${items.length})` + RESET);
    console.log(titleColor + '='.repeat(80) + RESET);
    
    const maxName = Math.max(12, ...items.map(i => i.name.length));
    const maxLocal = Math.max(5, ...items.map(i => i.localVersion.length));
    const maxNpm = Math.max(5, ...items.map(i => (i.npmVersion || 'N/A').length));
    
    const headerName = 'Package Name'.padEnd(maxName);
    const headerLocal = 'Local'.padEnd(maxLocal);
    const headerNpm = 'NPM'.padEnd(maxNpm);
    console.log(`${BOLD}${headerName}  ${headerLocal}  ${headerNpm}  Path${RESET}`);
    console.log('-'.repeat(80));
    
    for (const item of items) {
      const name = item.name.padEnd(maxName);
      const local = item.localVersion.padEnd(maxLocal);
      const npm = (item.npmVersion || 'N/A').padEnd(maxNpm);
      console.log(`${name}  ${local}  ${npm}  ${item.path}`);
    }
  }

  if (onlyCritical) {
    printTable('🔴  CRITICAL: NPM Version is Newer than Local', RED, critical);
  } else {
    printTable('🔴  CRITICAL: NPM Version is Newer than Local', RED, critical);
    printTable('🟡  INFO: Local Version is Ahead (Unreleased Changes)', YELLOW, ahead);
    printTable('🔵  NEW: Not Published on NPM Registry', CYAN, unreleased);
    
    if (showAll) {
      printTable('🟢  MATCH: Version Matches Registry', GREEN, matches);
    }
    
    if (errors.length > 0) {
      console.log('\n' + RED + '='.repeat(80) + RESET);
      console.log(RED + `⚠️   ERRORS: Failed to Check Registry (${errors.length})` + RESET);
      console.log(RED + '='.repeat(80) + RESET);
      for (const e of errors) {
        console.log(`${BOLD}${e.name}${RESET} (Local: ${e.localVersion}) at ${e.path}: ${RED}${e.error}${RESET}`);
      }
    }
  }

  // Print final summary
  console.log('\n' + BOLD + '='.repeat(40) + ' SUMMARY ' + '='.repeat(40) + RESET);
  console.log(`Total Checked Packages: ${BOLD}${results.length}${RESET}`);
  console.log(`Matches:                ${GREEN}${matches.length}${RESET}`);
  console.log(`Local Ahead:            ${YELLOW}${ahead.length}${RESET}`);
  console.log(`Unreleased:             ${CYAN}${unreleased.length}${RESET}`);
  console.log(`Critical Discrepancies: ${critical.length > 0 ? RED : GREEN}${critical.length}${RESET}`);
  
  if (errors.length > 0) {
    console.log(`Errors:                 ${RED}${errors.length}${RESET}`);
  }
  console.log(BOLD + '='.repeat(89) + RESET);

  if (critical.length > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
});
